import re
import sys

values = {}
pattern = re.compile(
    r"\b(TMP|[abcd])\s*<-\s*(?:(\d+)|"
    r"\(\s*(TMP|[abcd])\s*\+\s*(\d+)\s*\)\s*mod\s*100)\s*;"
)

for match in pattern.finditer(sys.stdin.read()):
    target, literal, source, increment = match.groups()
    if literal is not None:
        values[target] = int(literal)
    else:
        values[target] = (values[source] + int(increment)) % 100

print("; ".join(f"{name} ?= {values[name]}" for name in ("a", "b", "c", "d", "TMP")) + ";")
